"""Document scope RBAC filter."""
from path_resolver import clean_scope, split_scope_segments
from audit_logger import format_access_attempt

def check_scope_access(allowed_scope: str, requested_scope: str) -> bool:
    """Verify if requested scope is permitted within the designated scope pattern."""
    allowed_segments = split_scope_segments(clean_scope(allowed_scope))
    requested_segments = split_scope_segments(clean_scope(requested_scope))

    # Check if the requested scope has at least as many segments as the allowed scope
    if len(requested_segments) < len(allowed_segments):
        return False

    # Check each segment of the allowed scope against the corresponding segment of the requested scope
    for i, allowed_segment in enumerate(allowed_segments):
        if allowed_segment == "*" and i < len(requested_segments):
            continue  # Wildcard matches any single segment
        elif allowed_segment == "**":
            # Double asterisk matches arbitrary multi-segment prefixes
            # This is a more complex case - for now, treat as exact match for simplicity
            # In a more advanced implementation, this would need to check prefix matches
            return requested_segments[:len(allowed_segments)] == allowed_segments
        elif i >= len(requested_segments) or allowed_segment != requested_segments[i]:
            return False

    # Ensure exact prefix match for sibling scope checking (SEC-903 fix)
    if len(allowed_segments) < len(requested_segments):
        # Check that we're not allowing access to a sibling scope
        # For example, "corp::public" should not allow access to "corp::public_internal"
        if len(allowed_segments) > 0:
            # Check the next segment after the allowed scope to see if it's a sibling path
            allowed_prefix = "::".join(allowed_segments)
            requested_prefix = "::".join(requested_segments[:len(allowed_segments)])
            if allowed_prefix == requested_prefix:
                # If prefixes match, check if the next segment is a sibling
                if len(allowed_segments) < len(requested_segments):
                    # Check if the next segment in requested scope is different from allowed
                    # This ensures we don't allow access to sibling scopes
                    next_segment_in_requested = requested_segments[len(allowed_segments)]
                    next_segment_in_allowed = allowed_segments[-1] if len(allowed_segments) > 0 else ""
                    # If we have a direct prefix match but a different next segment, deny access
                    if next_segment_in_requested != next_segment_in_allowed:
                        return False

    return True

def filter_accessible_scopes(allowed_scope: str, scopes: list) -> list:
    return [s for s in scopes if check_scope_access(allowed_scope, s)]

def can_access_all_scopes(allowed_scope: str, scopes: list) -> bool:
    return all(check_scope_access(allowed_scope, s) for s in scopes)
